import { test, expect } from '@playwright/test';

test.describe('Checkout Form Validation', () => {
  test('should submit the form with valid data', async ({ page }) => {
    await test.beforeEach(async ({ page }) => {
      await page.goto('https://www.saucedemo.com/');
      await page.fill('input[name="firstName"]', 'Saif');
      await page.fill('input[name="lastName"]', 'Afzal');
      await page.click('input[name="continue"]');
    });
    await expect(page).toHaveURL(/.*checkout/);
  });

  test('should not submit the form with missing required fields', async ({ page }) => {
    await test.beforeEach(async ({ page }) => {
      await page.goto('https://www.saucedemo.com/');
      await page.click('a[data-test="add-to-cart-sauce-labs-backpack"]');
      await page.click('a[data-test="checkout"]');
      await page.click('input[name="continue"]');
    });
    await expect(page).toHaveURL(/.*checkout/);
    await expect(page.locator('a[data-test="continue"]')).toBeVisible();
  });
});
